def pos():
    seg = current_frame.segmentation
    out=[]
    for n in seg['nodes']:
        if n['color'] in 'bcMY':
            b=n['boundary']
            rs=[p[0] for p in b]; cs=[p[1] for p in b]
            out.append((n['color'], min(rs),min(cs),max(rs),max(cs),n['pixels']))
    return sorted(out)
